private static func decimal(_ value: Int64?) -> String {
    guard let value else {
        return ""
    }

    // 100倍整数から正確に戻す。Doubleへの変換・丸めは行わない。
    let whole = value.magnitude / 100
    let fraction = value.magnitude % 100
    let sign = value < 0 ? "-" : ""
    guard fraction != 0 else {
        return "\(sign)\(whole)"
    }

    let digits = fraction < 10 ? "0\(fraction)" : "\(fraction)"
    return "\(sign)\(whole).\(digits)"
}

private func numberField(
    _ title: String, text: Binding<String>, unit: String, field: ProductDraft.Field, id: String,
    requirement: String = "任意"
) -> some View {
    VStack(alignment: .leading, spacing: 4) {
        Text(unit.isEmpty ? title : "\(title)（\(unit)）")
            .font(.subheadline)
        TextField("未設定", text: text)
            .keyboardType(.numbersAndPunctuation)
            .textInputAutocapitalization(.never)
            .autocorrectionDisabled()
            .accessibilityLabel("\(title)、\(unit)、\(requirement)")
            .accessibilityHint(validationMessage(field) ?? "空欄は未設定です。")
            .accessibilityIdentifier("product-form-\(id)")
        fieldError(field, title: title, id: id)
    }
}

@ViewBuilder
private func fieldError(_ field: ProductDraft.Field, title: String, id: String) -> some View {
    if let message = validationMessage(field) {
        Text(message)
            .foregroundStyle(.red)
            .fixedSize(horizontal: false, vertical: true)
            .accessibilityLabel("\(title)のエラー、\(message)")
            .accessibilityIdentifier("product-form-\(id)-error")
    }
}

mutating func save(
    using actions: ProductActions, onSave: @MainActor (UUID) -> Void
) -> Result<UUID, ProductActions.ActionError> {
    if let savedProductID {
        return .success(savedProductID)
    }

    switch persist(using: actions) {
    case .success(let productID):
        savedProductID = productID
        error = nil
        onSave(productID)
        return .success(productID)
    case .failure(let failure):
        error = failure
        return .failure(failure)
    }
}

private func persist(using actions: ProductActions) -> Result<UUID, ProductActions.ActionError> {
    guard let product else {
        return actions.create(from: draft).map { $0.id }
    }

    guard !product.isDeleted, product.modelContext != nil else {
        return .failure(.productNotInContext)
    }

    // 画像の入力欄はないため、保存直前の画像を引き継ぐ。
    let productID = product.id
    return actions.update(product, from: draft, image: product.image).map { productID }
}

